1	import { db } from "@/lib/db";
2	import { requireUser } from "@/lib/auth";
3	import { scanForSecrets } from "@/lib/secret-scan";
4	import { blockingFindings, moderateForPublish, recordModerationFindings } from "@/lib/moderation";
5	import { checkPublishRateLimit } from "@/lib/rate-limit";
6	import { track, EVENTS } from "@/lib/events";
7	
8	export const dynamic = "force-dynamic";
9	
10	const SITES_BASE = process.env.KODELY_SITES_BASE ?? "kodely.site";
11	
12	// Publishing snapshots the draft tree onto the published tree. Deliberately
13	// NOT deploying to real Nxeon hosting infra in Phase 1 — that provisioner is
14	// still gated (see the Nxeon shared-hosting security review), so *.kodely.site
15	// is served straight out of this app from the published rows.
16	//
17	// The *.kodely.site wildcard's nginx block only routes to the PROD app
18	// (port 3000) — there is no separate wildcard for staging. A project
19	// published from staging would otherwise return a *.kodely.site URL that
20	// resolves through prod's app against prod's database, where the slug
21	// doesn't exist. Deriving the mode from the request's own Host header (never
22	// touches DNS, nginx, or .env) means staging always gets a URL that resolves
23	// against itself.
24	export async function POST(req: Request, { params }: { params: Promise<{ id: string }> }) {
25	  const user = await requireUser().catch(() => null);
26	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
27	  const { id } = await params;
28	
29	  const project = await db.project.findFirst({
30	    where: { id, userId: user.id },
31	    include: {
32	      files: { where: { published: false, kind: "build" } },
33	    },
34	  });
35	  if (!project) return Response.json({ error: "Project not found." }, { status: 404 });
36	  if (project.files.length === 0) {
37	    return Response.json({ error: "Nothing to publish yet — generate a site first." }, { status: 400 });
38	  }
39	
40	  // Only gate genuinely new subdomains — republishing an already-live project
41	  // isn't the spam-farming vector this protects against.
42	  if (!project.publishedAt) {
43	    const rateLimit = await checkPublishRateLimit(user.id);
44	    if (!rateLimit.allowed) {
45	      return Response.json(
46	        { error: "You've published a lot of new sites today — try again tomorrow." },
47	        { status: 429, headers: { "Retry-After": String(rateLimit.retryAfterSeconds) } },
48	      );
49	    }
50	  }
51	
52	  // Scan both the compiled output (what's actually served) and the source
53	  // (a comment or string that got stripped by the build can still leak if
54	  // someone reads it another way) — belt and suspenders, cheap either way.
55	  const sourceFiles = await db.projectFile.findMany({
56	    where: { projectId: id, published: false, kind: "source" },
57	  });
58	  const publishable = [...project.files, ...sourceFiles].map((f) => ({
59	    path: f.path,
60	    content: f.content,
61	  }));
62	
63	  const leaks = scanForSecrets(publishable);
64	  if (leaks.length > 0) {
65	    const { path, kind } = leaks[0];
66	    return Response.json(
67	      { error: `Publishing blocked: found what looks like a real secret in ${path} (${kind}). Remove it and try again.` },
68	      { status: 400 },
69	    );
70	  }
71	
72	  // Abuse check. Same last-gate position as the secret scan, for the same
73	  // reason: after this line the files are reachable at *.kodely.site by anyone,
74	  // and a phishing clone hosted there is Kodely's abuse report to answer.
75	  //
76	  // moderateForPublish returns SIGNALS, not a verdict (see lib/moderation.ts) —
77	  // policy is applied right here, and only `high` refuses. Everything below
78	  // `high` is expected to be mostly benign (an integration logo, a mock login
79	  // UI) and must not stand between a legitimate user and their own site.
80	  const moderation = await moderateForPublish(publishable);
81	  const blockers = blockingFindings(moderation);
82	
83	  // Record BEFORE the policy branch, so the blocked path cannot return without
84	  // its rows: a refused publish leaves no other trace anywhere: no published
85	  // files, no event, nothing on the project. These rows are the only evidence
86	  // it happened.
87	  //
88	  // Awaited, not fire-and-forget like track() above — the full argument is on
89	  // recordModerationFindings() in lib/moderation.ts. The short version: this is
90	  // a moderation record about one identifiable site, not an aggregate metric,
91	  // a floating promise is not guaranteed to complete once we return a Response,
92	  // and the call cannot throw or change the outcome either way. Whatever this
93	  // line does, the publish below behaves exactly as it did before it existed.
94	  await recordModerationFindings({ projectId: id, result: moderation, blocked: blockers });
95	
96	  if (blockers.length > 0) {
97	    const worst = blockers[0];
98	    console.warn(
99	      `[kodely] publish blocked by moderation project=${id} user=${user.id} provider=${moderation.provider}`,
100	      blockers.map((f) => ({ rule: f.rule, path: f.path, evidence: f.evidence })),
101	    );
102	    return Response.json(
103	      {
104	        error: `Publishing blocked: ${worst.note} (${worst.path} — "${worst.evidence}"). If this is a mistake, edit the page or reply here and we'll take a look.`,
105	        moderation: { rule: worst.rule, path: worst.path },
106	      },
107	      { status: 400 },
108	    );
109	  }
110	  if (moderation.findings.length > 0) {
111	    // ModerationFinding is now the durable record; this stays as an operational
112	    // breadcrumb and is the one place that still shows EVERY occurrence. The
113	    // table records a non-blocking finding once per distinct (rule, file,
114	    // snippet) and skips exact repeats on republish — see the volume note in
115	    // lib/moderation.ts — so "fired again on an unchanged page" is a log
116	    // question, not a query.
117	    console.warn(
118	      `[kodely] publish moderation signals project=${id} user=${user.id} provider=${moderation.provider}`,
119	      moderation.findings.map((f) => ({ rule: f.rule, severity: f.severity, path: f.path })),
120	    );
121	  }
122	
123	  await db.$transaction([
124	    db.projectFile.deleteMany({ where: { projectId: id, published: true, kind: "build" } }),
125	    db.projectFile.createMany({
126	      data: project.files.map((f) => ({
127	        projectId: id,
128	        path: f.path,
129	        content: f.content,
130	        published: true,
131	        kind: "build",
132	      })),
133	    }),
134	    db.project.update({ where: { id }, data: { publishedAt: new Date() } }),
135	  ]);
136	
137	  // The North Star. `firstPublish` separates "reached the promise for the
138	  // first time" from a routine republish — the funnel counts the former.
139	  track(EVENTS.sitePublished, {
140	    userId: user.id,
141	    props: {
142	      projectId: id,
143	      slug: project.slug,
144	      firstPublish: !project.publishedAt,
145	      files: project.files.length,
146	    },
147	  });
148	
149	  const host = req.headers.get("host") ?? "";
150	  const url = host.includes("staging")
151	    ? `https://${host}/api/site/${project.slug}`
152	    : `https://${project.slug}.${SITES_BASE}`;
153	
154	  return Response.json({ url });
155	}
