1	import { cookies } from "next/headers";
2	import { db } from "@/lib/db";
3	import { createSession } from "@/lib/auth";
4	import { grantCredits, SIGNUP_GRANT } from "@/lib/credits";
5	import { createSeedProject } from "@/lib/seed-project";
6	import { track, EVENTS } from "@/lib/events";
