1	import { getCurrentUser } from "@/lib/auth";
2	import { checkEnhanceRateLimit } from "@/lib/rate-limit";
3	import { enhancePrompt, MAX_PROMPT_CHARS } from "@/lib/enhance";
4	
5	export const dynamic = "force-dynamic";
6	// Well above lib/enhance.ts's own SDK_TIMEOUT_MS so the deadline that fires is
7	// ours, with a friendly message, rather than the platform's blank 504.
8	export const maxDuration = 90;
9	
10	// Expand a rough prompt into a spec the user reviews and edits before
11	// building. Auth-gated like every other route that costs us money, but
12	// deliberately NOT credit-gated: this is the anti-bill-shock lever, and a
13	// preview of what you're about to buy cannot itself cost credits. See the
14	// header comment in lib/enhance.ts.
15	export async function POST(req: Request) {
16	  const user = await getCurrentUser();
17	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
18	
19	  const body = (await req.json().catch(() => null)) as { prompt?: string } | null;
20	  const prompt = body?.prompt?.trim();
21	
22	  if (!prompt) {
23	    return Response.json(
24	      { error: "Describe your site first — then Enhance can fill it out." },
25	      { status: 400 },
26	    );
27	  }
28	  if (prompt.length > MAX_PROMPT_CHARS) {
29	    return Response.json(
30	      { error: "That's already detailed enough to build — go ahead and build it." },
31	      { status: 400 },
32	    );
33	  }
34	
35	  const rateLimit = checkEnhanceRateLimit(user.id);
36	  if (!rateLimit.allowed) {
37	    return Response.json(
38	      { error: "You've enhanced a lot of prompts just now — try again shortly." },
39	      { status: 429, headers: { "Retry-After": String(rateLimit.retryAfterSeconds) } },
40	    );
41	  }
42	
43	  try {
44	    // req.signal aborts the model call if the tab closes or the user gives up
45	    // and hits Build instead — no reason to keep paying for an answer nobody
46	    // is waiting for.
47	    const spec = await enhancePrompt(prompt, req.signal);
48	    return Response.json({ spec });
49	  } catch (error) {
50	    // Timeout, refusal, empty answer, SDK not authenticated — the client's
51	    // response is identical, and it always points back at the thing that
52	    // still works. Enhance failing must never block a build.
53	    console.error("[kodely] enhance failed", error);
54	    return Response.json(
55	      { error: "Couldn't expand that just now — you can still build with what you wrote." },
56	      { status: 502 },
57	    );
58	  }
59	}
