1	import { getCurrentUser } from "@/lib/auth";
2	import {
3	  accountTooNew,
4	  grantReward,
5	  hashFromPendingReason,
6	  isPlatformConfigured,
7	  MIN_ACCOUNT_AGE_HOURS,
8	  pendingClaim,
9	  UNVERIFIED_HOLD_HOURS,
10	} from "../../_lib";
11	import { isUnverifiedPlatform } from "../_unverified";
12	
13	export const dynamic = "force-dynamic";
14	
15	// Step 2 of the UNVERIFIED path — see ../_unverified.ts. This DOES move money,
16	// so every gate is re-checked here rather than trusted from step 1: the hold
17	// is recomputed from the pending row's own createdAt (not from anything the
18	// client sends), and the identity hash comes out of the stored reason string
19	// rather than being re-derived from a handle the client could swap.
20	
21	export async function POST(req: Request) {
22	  const user = await getCurrentUser();
23	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
24	
25	  const body = (await req.json().catch(() => null)) as { platform?: unknown } | null;
26	  const platform = body?.platform;
27	
28	  if (!isUnverifiedPlatform(platform)) {
29	    return Response.json({ error: "Unknown reward." }, { status: 400 });
30	  }
31	  if (!isPlatformConfigured(platform)) {
32	    return Response.json({ error: "That reward isn't available." }, { status: 404 });
33	  }
34	  if (accountTooNew(user.createdAt)) {
35	    return Response.json(
36	      { error: `Rewards unlock ${MIN_ACCOUNT_AGE_HOURS} hours after signup.` },
37	      { status: 403 },
38	    );
39	  }
40	
41	  const pending = await pendingClaim(user.id, platform);
42	  if (!pending) {
43	    return Response.json({ error: "Connect an account first." }, { status: 409 });
44	  }
45	
46	  const readyAt = pending.createdAt.getTime() + UNVERIFIED_HOLD_HOURS * 3_600_000;
47	  if (Date.now() < readyAt) {
48	    return Response.json(
49	      { error: "Not ready yet.", readyAt: new Date(readyAt).toISOString() },
50	      { status: 425 },
51	    );
52	  }
53	
54	  const hash = hashFromPendingReason(pending.reason);
55	  if (hash === null) {
56	    console.error(`[rewards] malformed pending reason for user ${user.id}: ${pending.reason}`);
57	    return Response.json({ error: "Rewards are unavailable right now." }, { status: 503 });
58	  }
59	
60	  const result = await grantReward(user.id, platform, hash);
61	  if (!result.ok) {
62	    const status =
63	      result.reason === "already_claimed" || result.reason === "identity_already_used"
64	        ? 409
65	        : result.reason === "velocity_tripped"
66	          ? 429
67	          : 503;
68	    return Response.json({ error: messageFor(result.reason), state: result.reason }, { status });
69	  }
70	
71	  return Response.json({ state: "claimed", credits: result.credits });
72	}
73	
74	function messageFor(reason: string): string {
75	  switch (reason) {
76	    case "already_claimed":
77	      return "You've already claimed this one.";
78	    case "identity_already_used":
79	      return "That account has already been used for this reward.";
80	    case "velocity_tripped":
81	      return "Reward claims are paused for a moment. Try again shortly.";
82	    default:
83	      return "Rewards are unavailable right now.";
84	  }
85	}
