1	import { timingSafeEqual } from "node:crypto";
2	import { cookies } from "next/headers";
3	import { getCurrentUser } from "@/lib/auth";
4	import {
5	  accountTooNew,
6	  discordConfig,
7	  grantReward,
8	  identityHash,
9	  originFromRequest,
10	} from "../../_lib";
11	
12	export const dynamic = "force-dynamic";
13	
14	// ── The VERIFIED path, step 2 ─────────────────────────────────────────────
15	//
16	// This is the only place in the whole feature where a grant is backed by an
17	// actual third-party check. The claim "this person is in our Discord" is
18	// answered by Discord, about the account that just authenticated to Discord,
19	// on a server-to-server call the browser never touches.
20	//
21	// The access token is used once, here, and never stored — not in the ledger,
22	// not in a cookie, not in a log. The only thing that survives this request is
23	// an HMAC of the Discord user id (see identityHash in ../../_lib.ts).
24	
25	const STATE_COOKIE = "kodely_discord_reward_state";
26	const API = "https://discord.com/api/v10";
27	/** Documented unversioned form; the resource endpoints below are pinned to v10. */
28	const TOKEN_URL = "https://discord.com/api/oauth2/token";
29	
30	/**
31	 * undici applies no overall request deadline by default (only a connect and a
32	 * headers timeout, the latter measured in minutes), so a stalled Discord call
33	 * would otherwise hold this route open far longer than a user will wait. A
34	 * timeout here surfaces as an abort, which the catch below turns into a
35	 * fail-closed "try again" — never a grant.
36	 */
37	const DISCORD_TIMEOUT_MS = 10_000;
38	
39	type TokenResponse = { access_token?: string; error?: string };
40	type DiscordUser = { id?: string };
41	
42	function done(origin: string, outcome: string): Response {
43	  return Response.redirect(`${origin}/settings?reward=${outcome}`, 302);
44	}
45	
46	/** Constant-time compare that tolerates unequal lengths without throwing. */
47	function safeEqual(a: string, b: string): boolean {
48	  const bufA = Buffer.from(a);
49	  const bufB = Buffer.from(b);
50	  if (bufA.length !== bufB.length) return false;
51	  return timingSafeEqual(bufA, bufB);
52	}
53	
54	export async function GET(req: Request) {
55	  const origin = originFromRequest(req);
56	  const url = new URL(req.url);
57	
58	  const jar = await cookies();
59	  const expectedState = jar.get(STATE_COOKIE)?.value;
60	  jar.delete(STATE_COOKIE);
61	
62	  const user = await getCurrentUser();
63	  if (!user) return Response.redirect(`${origin}/login`, 302);
64	
65	  const config = discordConfig();
66	  if (!config) {
67	    console.error("[rewards] Discord callback reached with no Discord config.");
68	    return done(origin, "unavailable");
69	  }
70	
71	  const code = url.searchParams.get("code");
72	  const state = url.searchParams.get("state");
73	
74	  // Three things have to line up: the state came back intact, it matches the
75	  // cookie we set, and it names the user whose session is making this request.
76	  // The last check is what stops a captured callback URL from being replayed
77	  // into someone else's browser to move a grant onto their account.
78	  if (!code || !state || !expectedState || !safeEqual(state, expectedState)) {
79	    return done(origin, "failed");
80	  }
81	  if (state.split(".")[1] !== user.id) return done(origin, "failed");
82	
83	  // Re-checked after the round trip, not just before it — the flow takes as
84	  // long as the user takes, and both of these can change in the meantime.
85	  if (accountTooNew(user.createdAt)) return done(origin, "too_new");
86	
87	  try {
88	    const tokenRes = await fetch(TOKEN_URL, {
89	      method: "POST",
90	      headers: { "Content-Type": "application/x-www-form-urlencoded" },
91	      body: new URLSearchParams({
92	        client_id: config.clientId,
93	        client_secret: config.clientSecret,
94	        grant_type: "authorization_code",
95	        code,
96	        redirect_uri: `${origin}/api/rewards/discord/callback`,
97	      }),
98	      signal: AbortSignal.timeout(DISCORD_TIMEOUT_MS),
99	    });
100	    const tokens = (await tokenRes.json()) as TokenResponse;
101	    if (!tokenRes.ok || !tokens.access_token) return done(origin, "failed");
102	
103	    const auth = { Authorization: `Bearer ${tokens.access_token}` };
104	
105	    const meRes = await fetch(`${API}/users/@me`, {
106	      headers: auth,
107	      signal: AbortSignal.timeout(DISCORD_TIMEOUT_MS),
108	    });
109	    const me = (await meRes.json()) as DiscordUser;
110	    if (!meRes.ok || !me.id) return done(origin, "failed");
111	
112	    // The verification itself. 200 means Discord returned a guild member
113	    // object for our guild — they are in it. 404 (Unknown Guild) means they
114	    // are not.
115	    //
116	    // Chosen over scanning `GET /users/@me/guilds` deliberately. That list is
117	    // capped at 200 per page, which is also roughly the account guild cap, so
118	    // a Nitro user in more than 200 servers would produce a FALSE NEGATIVE on
119	    // a naive single-page scan — a real user denied a real reward. It also
120	    // asks for a much broader consent ("see all your servers") to answer a
121	    // one-bit question.
122	    //
123	    // Honest limit of even this check: it is a snapshot. Nothing stops
124	    // join -> verify -> leave. The member object carries `joined_at` if we
125	    // ever want to require tenure, but a 50-credit reward does not justify
126	    // that friction today.
127	    const memberRes = await fetch(`${API}/users/@me/guilds/${config.guildId}/member`, {
128	      headers: auth,
129	      signal: AbortSignal.timeout(DISCORD_TIMEOUT_MS),
130	    });
131	
132	    if (memberRes.status === 404) return done(origin, "not_member");
133	    if (!memberRes.ok) {
134	      // Anything else — 401, 403, a 429 rate limit, a Discord outage — is an
135	      // INCONCLUSIVE answer, and inconclusive must never pay out. Fail closed
136	      // and tell the user to retry; a false negative costs a retry, a false
137	      // positive costs real money.
138	      console.error(`[rewards] Discord member check returned ${memberRes.status}`);
139	      return done(origin, "failed");
140	    }
141	
142	    const hash = identityHash("discord", me.id);
143	    if (hash === null) {
144	      console.error("[rewards] KODELY_REWARDS_ID_SALT is not set — refusing to grant.");
145	      return done(origin, "unavailable");
146	    }
147	
148	    const result = await grantReward(user.id, "discord", hash);
149	    if (result.ok) return done(origin, "discord_ok");
150	
151	    switch (result.reason) {
152	      case "already_claimed":
153	        return done(origin, "already");
154	      // The Discord account itself has already earned this on some other
155	      // Kodely account. This is the check that stops one Discord login from
156	      // farming fifty signups, and it is the one that will actually fire.
157	      case "identity_already_used":
158	        return done(origin, "discord_taken");
159	      case "velocity_tripped":
160	        return done(origin, "paused");
161	      default:
162	        return done(origin, "unavailable");
163	    }
164	  } catch (err) {
165	    console.error("[rewards] Discord verification failed:", err);
166	    return done(origin, "failed");
167	  }
168	}
