// TEMPORARY verification harness for the feature-flag wiring. Deleted when done.
import { PrismaClient } from "@prisma/client";
const db = new PrismaClient();
const cmd = process.argv[2];

if (cmd === "state") {
  console.log("flags:", JSON.stringify(await db.featureFlag.findMany(), null, 2));
  console.log("counts", {
    users: await db.user.count(),
    projects: await db.project.count(),
    builds: await db.build.count(),
    ledger: await db.creditLedger.count(),
    files: await db.projectFile.count(),
    messages: await db.message.count(),
    rewards: await db.rewardClaim.count().catch(() => "n/a"),
  });
} else if (cmd === "set") {
  const key = process.argv[3];
  const enabled = process.argv[4] === "true";
  const pct = Number(process.argv[5] ?? 100);
  await db.featureFlag.upsert({
    where: { key },
    create: { key, enabled, rolloutPct: pct, description: "flagcheck temp", updatedBy: "flagcheck" },
    update: { enabled, rolloutPct: pct },
  });
  console.log("set", key, enabled, pct);
} else if (cmd === "del") {
  const key = process.argv[3];
  console.log(await db.featureFlag.deleteMany({ where: { key } }));
}
await db.$disconnect();

