// TEMPORARY verification harness for the feature-flag wiring. Deleted when done.
import { PrismaClient } from "@prisma/client";
import { randomBytes, createHash } from "node:crypto";

const db = new PrismaClient();
const cmd = process.argv[2];
const TAG = "flagtest";
const hashToken = (t) => createHash("sha256").update(t).digest("hex");

async function counts() {
  return {
    users: await db.user.count(),
    projects: await db.project.count(),
    builds: await db.build.count(),
    ledger: await db.creditLedger.count(),
    files: await db.projectFile.count(),
    messages: await db.message.count(),
    sessions: await db.session.count(),
  };
}

if (cmd === "state") {
  console.log("flags:", JSON.stringify(await db.featureFlag.findMany()));
  console.log("counts:", JSON.stringify(await counts()));
} else if (cmd === "counts") {
  console.log(JSON.stringify(await counts()));
} else if (cmd === "set") {
  const [key, enabled, pct] = process.argv.slice(3);
  await db.featureFlag.upsert({
    where: { key },
    create: {
      key,
      enabled: enabled === "true",
      rolloutPct: Number(pct ?? 100),
      description: "flagcheck temp",
      updatedBy: TAG,
    },
    update: { enabled: enabled === "true", rolloutPct: Number(pct ?? 100) },
  });
  console.log("set", key, enabled, pct ?? 100);
} else if (cmd === "delflag") {
  console.log(JSON.stringify(await db.featureFlag.deleteMany({ where: { key: process.argv[3] } })));
} else if (cmd === "seed") {
  // A user + session + project + one build file, created directly so the tests
  // do not depend on the signup route (which is itself under test).
  const user = await db.user.create({
    data: { email: `${TAG}-a@kodely.invalid`, name: "Flag Test A", passwordHash: "scrypt$00$00" },
  });
  await db.creditLedger.create({
    data: { userId: user.id, delta: 750, reason: "signup_grant", balanceAfter: 750 },
  });
  const project = await db.project.create({
    data: { userId: user.id, name: "Flag Test Site", slug: `${TAG}-site-${Date.now()}` },
  });
  await db.projectFile.createMany({
    data: [
      {
        projectId: project.id,
        path: "index.html",
        content: "<!doctype html><title>flagtest</title>",
        published: false,
        kind: "build",
      },
      {
        projectId: project.id,
        path: "src/App.tsx",
        content: "export default function App(){return null}",
        published: false,
        kind: "source",
      },
    ],
  });
  const token = randomBytes(32).toString("base64url");
  await db.session.create({
    data: {
      userId: user.id,
      tokenHash: hashToken(token),
      expiresAt: new Date(Date.now() + 86_400_000),
    },
  });
  console.log(JSON.stringify({ userId: user.id, projectId: project.id, token }));
} else if (cmd === "project") {
  const p = await db.project.findUnique({ where: { id: process.argv[3] } });
  console.log(
    JSON.stringify({
      publishedAt: p?.publishedAt ?? null,
      publishedFiles: await db.projectFile.count({
        where: { projectId: process.argv[3], published: true },
      }),
      builds: await db.build.count({ where: { projectId: process.argv[3] } }),
      messages: await db.message.count({ where: { projectId: process.argv[3] } }),
    }),
  );
} else if (cmd === "drain") {
  // Take the test user's balance to exactly zero.
  const userId = process.argv[3];
  const rows = await db.creditLedger.findMany({ where: { userId } });
  const bal = rows.reduce((s, r) => s + r.delta, 0);
  await db.creditLedger.create({
    data: { userId, delta: -bal, reason: "flagtest_drain", balanceAfter: 0 },
  });
  console.log("drained", bal);
} else if (cmd === "cleanup") {
  const users = await db.user.findMany({ where: { email: { contains: TAG } } });
  for (const u of users) {
    const projects = await db.project.findMany({ where: { userId: u.id } });
    for (const p of projects) {
      await db.projectFile.deleteMany({ where: { projectId: p.id } });
      await db.message.deleteMany({ where: { projectId: p.id } });
      await db.build.deleteMany({ where: { projectId: p.id } });
      await db.moderationFinding.deleteMany({ where: { projectId: p.id } });
    }
    await db.project.deleteMany({ where: { userId: u.id } });
    await db.creditLedger.deleteMany({ where: { userId: u.id } });
    await db.session.deleteMany({ where: { userId: u.id } });
    await db.event.deleteMany({ where: { userId: u.id } });
    await db.user.delete({ where: { id: u.id } });
  }
  const flags = await db.featureFlag.deleteMany({ where: { updatedBy: TAG } });
  console.log(JSON.stringify({ usersDeleted: users.length, flagsDeleted: flags.count }));
}

await db.$disconnect();

